/* B"H */
#include "include/awts_native_browser.h"

static AwtsBrowserState g_state;

static LRESULT CALLBACK AwtsWndProc(HWND hwnd, UINT msg, WPARAM wp, LPARAM lp) {
  switch (msg) {
    case WM_CLOSE:
    case WM_DESTROY:
      g_state.running = 0;
      PostQuitMessage(0);
      return 0;
  }
  return DefWindowProc(hwnd, msg, wp, lp);
}

static void awts_prepare_sample_state(AwtsBrowserState* state) {
  memset(state, 0, sizeof(*state));
  state->running = 1;
  state->width = 960;
  state->height = 540;
  strncpy(state->statusText, "ready", sizeof(state->statusText) - 1);
  strncpy(state->url, "file:///index.html", sizeof(state->url) - 1);
  awts_scan_webgl(&state->webgl, AWTS_SAMPLE_JS);
}

int awts_launch_browser(const char* bytecodePath) {
  awts_prepare_sample_state(&g_state);
  awts_load_merkava_file(&g_state, bytecodePath);

  printf("B'H Merkava Native Browser / Runtime Executor\n");
  printf("bytecode=%s bytes=%u ok=%u section=%u version=%u\n", bytecodePath, g_state.bytecodeLen, g_state.bytecodeOk, g_state.section, g_state.version);
  printf("sample-app=frontend.html app.js navigator-ui=enabled\n");
  awts_print_webgl_table(&g_state.webgl);
  awts_print_runtime_report();
  fflush(stdout);

  HINSTANCE hInst = GetModuleHandle(NULL);
  WNDCLASS wc;
  ZeroMemory(&wc, sizeof(wc));
  wc.style = CS_OWNDC;
  wc.lpfnWndProc = AwtsWndProc;
  wc.hInstance = hInst;
  wc.lpszClassName = "AwtsMerkavaNativeBrowser";
  wc.hCursor = LoadCursor(NULL, IDC_ARROW);
  if (!RegisterClass(&wc)) { printf("register_window_failed=%lu\n", GetLastError()); return 10; }

  HWND hwnd = CreateWindowEx(0, wc.lpszClassName, "B'H Merkava Navigator - Native OpenGL/WebGL Bridge", WS_OVERLAPPEDWINDOW | WS_VISIBLE, CW_USEDEFAULT, CW_USEDEFAULT, g_state.width, g_state.height, NULL, NULL, hInst, NULL);
  if (!hwnd) { printf("create_window_failed=%lu\n", GetLastError()); return 11; }

  HDC dc = GetDC(hwnd);
  PIXELFORMATDESCRIPTOR pfd;
  ZeroMemory(&pfd, sizeof(pfd));
  pfd.nSize = sizeof(pfd);
  pfd.nVersion = 1;
  pfd.dwFlags = PFD_DRAW_TO_WINDOW | PFD_SUPPORT_OPENGL | PFD_DOUBLEBUFFER;
  pfd.iPixelType = PFD_TYPE_RGBA;
  pfd.cColorBits = 32;
  pfd.cDepthBits = 24;
  pfd.iLayerType = PFD_MAIN_PLANE;
  int pf = ChoosePixelFormat(dc, &pfd);
  if (!pf || !SetPixelFormat(dc, pf, &pfd)) { printf("pixel_format_failed=%lu\n", GetLastError()); return 12; }
  HGLRC rc = wglCreateContext(dc);
  if (!rc || !wglMakeCurrent(dc, rc)) { printf("opengl_context_failed=%lu\n", GetLastError()); return 13; }

  printf("opengl_vendor=%s\n", glGetString(GL_VENDOR));
  printf("opengl_renderer=%s\n", glGetString(GL_RENDERER));
  printf("opengl_version=%s\n", glGetString(GL_VERSION));
  fflush(stdout);

  MSG msg;
  DWORD start = GetTickCount();
  while (g_state.running && GetTickCount() - start < 2800) {
    while (PeekMessage(&msg, NULL, 0, 0, PM_REMOVE)) {
      if (msg.message == WM_QUIT) g_state.running = 0;
      TranslateMessage(&msg);
      DispatchMessage(&msg);
    }
    awts_draw_native_browser(&g_state);
    SwapBuffers(dc);
    g_state.frames++;
    Sleep(16);
  }

  wglMakeCurrent(NULL, NULL);
  if (rc) wglDeleteContext(rc);
  ReleaseDC(hwnd, dc);
  DestroyWindow(hwnd);
  printf("frames=%d loaded=%d renderer=win32-opengl navigator-ui=drawn webgl-bridge=viewport-clearColor-clear-drawArrays status=complete\n", g_state.frames, g_state.loaded);
  fflush(stdout);
  return g_state.loaded ? 0 : 2;
}

int main(int argc, char** argv) {
  if (argc > 1 && (!strcmp(argv[1], "--help") || !strcmp(argv[1], "-h"))) { awts_print_help(); return 0; }
  if (argc > 1 && (!strcmp(argv[1], "--version") || !strcmp(argv[1], "-v"))) { printf("merkavaapp native 0.4.0\n"); return 0; }
  if (argc > 2 && !strcmp(argv[1], "--check")) {
    if (awts_ends_with(argv[2], ".js")) return awts_analyze_js(argv[2], 1);
    if (awts_ends_with(argv[2], ".html") || awts_ends_with(argv[2], ".htm")) return awts_analyze_html(argv[2], 1);
    if (awts_ends_with(argv[2], ".merkava")) {
      AwtsBrowserState check;
      memset(&check, 0, sizeof(check));
      int ok = awts_load_merkava_file(&check, argv[2]);
      printf("B'H Merkava bytecode check\nfile=%s bytes=%u ok=%u section=%u version=%u\n", argv[2], check.bytecodeLen, check.bytecodeOk, check.section, check.version);
      return ok ? 0 : 2;
    }
    printf("--check unsupported file type: %s\n", argv[2]); return 64;
  }
  if (argc > 1 && awts_ends_with(argv[1], ".js")) return awts_analyze_js(argv[1], 0);
  if (argc > 1 && (awts_ends_with(argv[1], ".html") || awts_ends_with(argv[1], ".htm"))) return awts_analyze_html(argv[1], 0);
  const char* bytecodePath = argc > 1 ? argv[1] : "sample.merkava";
  return awts_launch_browser(bytecodePath);
}

