#include "include/awts_native_browser.h"

static void awts_gl_rect(float x, float y, float w, float h, float r, float g, float b) {
  glColor3f(r, g, b);
  glBegin(GL_QUADS);
    glVertex2f(x, y);
    glVertex2f(x + w, y);
    glVertex2f(x + w, y + h);
    glVertex2f(x, y + h);
  glEnd();
}

static void awts_gl_outline(float x, float y, float w, float h, float r, float g, float b) {
  glColor3f(r, g, b);
  glBegin(GL_LINE_LOOP);
    glVertex2f(x, y);
    glVertex2f(x + w, y);
    glVertex2f(x + w, y + h);
    glVertex2f(x, y + h);
  glEnd();
}

static void awts_gl_triangle(float cx, float cy, float s, float pulse) {
  glBegin(GL_TRIANGLES);
    glColor3f(1.0f, 0.25f + pulse * 0.2f, 0.15f); glVertex2f(cx - s, cy - s * 0.72f);
    glColor3f(0.1f, 0.9f, 0.35f);                  glVertex2f(cx + s, cy - s * 0.72f);
    glColor3f(0.25f, 0.45f, 1.0f);                 glVertex2f(cx,     cy + s);
  glEnd();
}

static void awts_gl_bar(float x, float y, float w, float value, float r, float g, float b) {
  awts_gl_rect(x, y, w * value, 0.035f, r, g, b);
  awts_gl_outline(x, y, w, 0.035f, 0.35f, 0.42f, 0.55f);
}

void awts_draw_native_browser(AwtsBrowserState* state) {
  float pulse = (float)((state->frames % 120) / 120.0f);
  state->pulse = pulse;
  glViewport(0, 0, state->width, state->height);
  glClearColor(0.012f, 0.016f + pulse * 0.035f, 0.035f, 1.0f);
  glClear(GL_COLOR_BUFFER_BIT);

  /* Browser chrome from sample navigator app */
  awts_gl_rect(-0.96f, 0.78f, 1.92f, 0.16f, 0.045f, 0.055f, 0.085f);
  awts_gl_rect(-0.90f, 0.82f, 0.08f, 0.05f, 0.95f, 0.25f, 0.22f);
  awts_gl_rect(-0.79f, 0.82f, 0.08f, 0.05f, 0.95f, 0.72f, 0.18f);
  awts_gl_rect(-0.68f, 0.82f, 0.08f, 0.05f, 0.18f, 0.82f, 0.35f);
  awts_gl_rect(-0.50f, 0.815f, 1.32f, 0.06f, 0.10f, 0.13f, 0.20f);
  awts_gl_outline(-0.50f, 0.815f, 1.32f, 0.06f, 0.30f, 0.40f, 0.62f);

  /* DOM-ish main panel */
  awts_gl_rect(-0.92f, -0.82f, 1.84f, 1.54f, 0.025f, 0.034f, 0.060f);
  awts_gl_outline(-0.92f, -0.82f, 1.84f, 1.54f, 0.20f, 0.34f, 0.58f);

  /* Canvas element from frontend.html */
  awts_gl_rect(-0.64f, -0.42f, 1.28f, 0.72f, 0.015f, 0.035f, 0.070f);
  awts_gl_outline(-0.64f, -0.42f, 1.28f, 0.72f, 0.25f, 0.55f, 0.88f);

  /* WebGL clearColor + drawArrays(TRIANGLES) visualized through OpenGL */
  awts_gl_triangle(0.0f, -0.05f, 0.33f, pulse);

  /* Button and output */
  awts_gl_rect(-0.28f, -0.64f, 0.22f, 0.095f, 0.14f, 0.30f, 0.60f);
  awts_gl_outline(-0.28f, -0.64f, 0.22f, 0.095f, 0.55f, 0.78f, 1.0f);
  awts_gl_rect(0.02f, -0.64f, 0.42f, 0.095f, 0.08f, 0.12f, 0.18f);
  awts_gl_outline(0.02f, -0.64f, 0.42f, 0.095f, 0.35f, 0.50f, 0.72f);

  /* Runtime/WebGL command table bars */
  awts_gl_bar(-0.82f, -0.74f, 0.45f, state->webgl.viewport ? 1.0f : 0.08f, 0.35f, 0.65f, 1.0f);
  awts_gl_bar(-0.28f, -0.74f, 0.45f, state->webgl.clearColor ? 1.0f : 0.08f, 0.30f, 0.95f, 0.55f);
  awts_gl_bar(0.26f, -0.74f, 0.45f, state->webgl.drawArrays ? 1.0f : 0.08f, 1.0f, 0.55f, 0.30f);

  /* Pulsing app loaded indicator */
  awts_gl_rect(-0.90f, -0.08f, 0.06f, 0.16f + pulse * 0.16f, 0.18f, 0.90f, 0.45f);
  awts_gl_rect(0.84f, -0.08f, 0.06f, 0.16f + (1.0f - pulse) * 0.16f, 0.90f, 0.35f, 0.20f);
}
